UPDATE alternativas SET texto = 'Suspender a eritropoietina e administrar ferro.' WHERE questao_id = 'SIM2023-02-007' AND letra = 'C';
UPDATE alternativas SET texto = 'Aumentar a dose de eritropoietina e administrar ferro.' WHERE questao_id = 'SIM2023-02-007' AND letra = 'D';
