UPDATE questoes SET enunciado = 'O diagnóstico mais provável de um paciente com anemia crónica há vários anos, com episódios hemolíticos agudos durante intercorrências infecciosas, que apresenta deficiência crónica de ferro e episódios repetidos de trombose venosa, com o seguinte estudo analítico: hemoglobina de 9,3 g/dL, reticulócitos = 18 x 10^9/L, leucócitos = 2,8 x 10^9/L, neutrófilos = 0,75 x 10^9/L e haptoglobina indetetável, é:', explicacao = 'Uma anemia hemolítica (haptoglobina indetetável) com dados de aplasia medular (pancitopenia com
 reticulócitos baixos, quando numa anemia hemolítica "pura" deveria haver reticulocitose) e episódios de
 trombose de repetição é o quadro clínico clássico de uma hemoglobinúria paroxística noturna.', updated_at = NOW() WHERE id = 'SIM2023-02-011';
