UPDATE alternativas SET texto = 'VS 10 mm/h. Hemoglobina 10 g/dL. Fosfatase alcalina elevada. Análise sumária de urina normal. Biópsia de veia auricular com infiltrado de neutrófilos.' WHERE questao_id = 'SIM2023-05-150' AND letra = 'C';
