UPDATE questoes SET enunciado = 'Um doente de 65 anos faz análises de rotina com os seguintes resultados concentração de hemoglobina 19 g/dL, valor de hematócrito 55%. O doente não tem hábitos tabágicos e a saturação arterial de oxigénio é de 95%. Que análise pode ser pedida para ajudar no estudo diagnóstico?', explicacao = 'A pergunta descreve-nos um quadro de poliglobulia (eritrocitose). São vários os exames que podem ser
 realizados para fazer diagnóstico diferencial mas em termos analíticos o estudo que melhor nos pode indicar
 se se trata de uma poliglobulia verdadeira ou espúria é a EPO sérica.', updated_at = NOW() WHERE id = 'SIM2023-08-147';
