UPDATE alternativas SET texto = 'Se não existir contraindicação médica, devemos considerar adicionar um anti-TNF alfa ao tratamento de base.' WHERE questao_id = 'SIM2023-11-076' AND letra = 'C';
UPDATE alternativas SET texto = 'Iniciar o mais rápido possível um segundo fármaco modificador da doença, uma vez que não se pode iniciar tratamento com biológicos após tratamento isolado com metotrexato.' WHERE questao_id = 'SIM2023-11-076' AND letra = 'D';
