UPDATE alternativas SET texto = 'Pedir rastreio HIV, iniciar terapêutica antirretroviral tripla imediatamente e oferecer a possibilidade de tomar acetato de ulipristal, método de contraceção de emergência.' WHERE questao_id = 'SIM2023-12-111' AND letra = 'D';
