UPDATE alternativas SET texto = 'Hemoglobinúria paroxística noturna.' WHERE questao_id = 'SIM2023-16-073' AND letra = 'C';
UPDATE alternativas SET texto = 'Aplasia eritroide pura.' WHERE questao_id = 'SIM2023-16-073' AND letra = 'D';
