UPDATE alternativas SET texto = 'Teremos de a estudar quanto à presença de uma mutação no gene BRCA 1, porque a idade de diagnóstico e o fenótipo do seu tumor sugerem que possa existir uma mutação nesse gene.»' WHERE questao_id = 'SIM2023-17-145' AND letra = 'B';
UPDATE alternativas SET texto = 'Teremos de a estudar quanto à presença de uma mutação no gene BRCA 2, porque a idade de diagnóstico e o fenótipo do seu tumor sugerem que possa existir uma mutação nesse gene.»' WHERE questao_id = 'SIM2023-17-145' AND letra = 'C';
UPDATE alternativas SET texto = 'Como não tem antecedentes familiares de cancro da mama ou do ovário, não é pertinente estudá-la quanto à presença de mutações nos genes BRCA 1 e BRCA 2.»' WHERE questao_id = 'SIM2023-17-145' AND letra = 'D';
