UPDATE alternativas SET texto = 'Associar sitagliptina.' WHERE questao_id = 'SIM2023-18-127' AND letra = 'C';
UPDATE alternativas SET texto = 'Associar pioglitazona em doses baixas, e aumentar segundo a tolerância e a necessidade.' WHERE questao_id = 'SIM2023-18-127' AND letra = 'D';
