UPDATE alternativas SET texto = 'Reidratação com solução de reidratação oral de baixa osmolaridade (sódio 60-75 mEq/L), manter a sua dieta habitual e amoxicilina oral 10 dias.' WHERE questao_id = 'SIM2023-19-117' AND letra = 'C';
UPDATE alternativas SET texto = 'Reidratação com solução de reidratação oral de baixa osmolaridade (sódio 60-75 mEq/L) e começar alimentação com fórmula sem lactose.' WHERE questao_id = 'SIM2023-19-117' AND letra = 'D';
