UPDATE alternativas SET texto = 'Haloperidol subcutâneo.' WHERE questao_id = 'SIM2023-23-008' AND letra = 'B';
UPDATE alternativas SET texto = 'Cateter vesical se há suspeita de retenção aguda de urina.' WHERE questao_id = 'SIM2023-23-008' AND letra = 'C';
UPDATE alternativas SET texto = 'Enemas se há suspeita de impactação fecal.' WHERE questao_id = 'SIM2023-23-008' AND letra = 'D';
