UPDATE alternativas SET texto = 'Medicar com fármacos beta 3 adrenérgicos.' WHERE questao_id = 'SIM2023-23-125' AND letra = 'C';
UPDATE alternativas SET texto = 'Administração de bulking agents na uretra.' WHERE questao_id = 'SIM2023-23-125' AND letra = 'D';
