UPDATE alternativas SET texto = 'Deverá realizar um teste de gravidez e, caso esta não se confirme, deverá aguardar pelo menos 1 ano após a vacinação para tentar engravidar.' WHERE questao_id = 'SIM2023-24-106' AND letra = 'C';
