UPDATE alternativas SET texto = '«Fico preocupado com a segurança da sua esposa e temos de a avisar. É necessário que ela venha cá ter.»' WHERE questao_id = 'SIM2023-25-082' AND letra = 'C';
UPDATE alternativas SET texto = '«Isso são tudo ideias da sua cabeça. No fundo deve estar a sentir-se culpado por alguma coisa que não me está a contar. Há algum problema na relação com a sua mulher?»' WHERE questao_id = 'SIM2023-25-082' AND letra = 'D';
