UPDATE alternativas SET texto = 'O risco de pré-eclâmpsia numa próxima gravidez é igual ao das outras mulheres sem antecedentes de doenças hipertensivas da gravidez.' WHERE questao_id = 'SIM2023-26-096' AND letra = 'D';
