UPDATE alternativas SET texto = 'Retirar o tubo endotorácico e repetir radiografia de tórax passadas 2 horas.' WHERE questao_id = 'SIM2023-27-139' AND letra = 'C';
UPDATE alternativas SET texto = 'Colocar um tubo adicional numa localização diferente que permita a resolução definitiva do quadro.' WHERE questao_id = 'SIM2023-27-139' AND letra = 'D';
