UPDATE alternativas SET texto = 'Vacina hexavalente (Haemophilus influenzae b; Difteria, tétano, tosse convulsa; Poliomielite; Hepatite B).' WHERE questao_id = 'SIM2023-30-002' AND letra = 'C';
