UPDATE alternativas SET texto = 'A associação da fratura do cúbito implica maior estabilidade da fratura.' WHERE questao_id = 'SIM2023-30-049' AND letra = 'B';
UPDATE alternativas SET texto = 'O tratamento é conservador.' WHERE questao_id = 'SIM2023-30-049' AND letra = 'C';
